import {fareRoutes,mergeBackendFares} from './fare-routes.mjs';
import {allocateCircuit} from './circuit.mjs';
import {freshScenario} from './scenario.mjs';
import {defaults,scoreTeam,plan,typicalCount,week,day,migrateHosts,seasonWeeks,scheduleSummary,strengthSeasons,teamRatings,competitionStrength,scheduleStrength,presets,scenarioWithPreset} from './model.mjs';
import {teamLocations,competitionLocations,labels,teamColors} from './locations.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'Unknown':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const fmt=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}):'Date missing';
const PUBLIC=document.documentElement.dataset.mode==='public';
const display=t=>labels[t]||t,KEY=PUBLIC?'raas-atlas-public-v1':'raas-atlas-v1';
const PUBLIC_FEED='https://raas-atlas-api.sunkarayashaswi.workers.dev/fares';
let strengthCompetition='';
let data,geo,state,tab='team',selected='UVA',detail=null,provider=false,message='',allResults,circuitView="calendar",compareTeams=["UVA","Northeastern"],compareMode="teams",connectionInfo={},advancedOpen=false,showStrength=false,fareScope='shortlist',refreshDays=7;
function fresh(){return freshScenario(data,geo);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent=PUBLIC?'Your preferences · this browser only':'Saved in this browser';}catch{$('#save-status').textContent='Browser storage unavailable';}allResults=null;}
function circuit(){return allResults??=allocateCircuit(data,state);}
function results(t=selected){return circuit().matrix[t];}
function all(){return circuit().matrix;}
function field(label,key,value,{min=0,max=100000,step=1,type='number',scope='setting'}={}){return `<label class="field"><span>${label}</span><input data-${scope}="${key}" type="${type}" value="${esc(value)}" min="${min}" max="${max}" step="${step}" required></label>`;}
function render(){controls();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const missingHosts=state.competitions.filter(c=>!c.hosts.length).map(c=>c.id);$('#notice').innerHTML=message?esc(message):`${missingHosts.length?`Host teams still need verification: <b>${missingHosts.join(', ')}</b>. `:''}Fares are saved planning estimates with retrieval dates; airport choices and other travel costs are editable assumptions.`;if(detail)renderDetail();else if(tab==='team')renderTeam();else if(tab==='circuit')renderCircuit();else if(tab==='compare')renderCompare();else if(tab==='inputs')renderInputs();else if(tab==='strength')renderStrength();else if(tab==='prices')renderPrices();else renderMethod();decorateTeams();}
function renderTeam(){const {rows,plan:season}=results(),chosen=new Set(season.rows.map(r=>r.competition.id)),p=state.teams[selected];const weeks=[...new Set(state.competitions.filter(c=>c.date).map(c=>week(c.date)))].sort((a,b)=>a-b);const sorted=[...rows].sort((a,b)=>Number(a.blocked)-Number(b.blocked)||(b.score??0)-(a.score??0));$('#content').innerHTML=`<div class="section-head"><div><h2>${teamBadge(selected)}</h2><p class="subtle">Your season, based on the last ${state.settings.lookback} recorded seasons.</p></div><span class="chip">2026–2027</span></div><div class="metrics"><div class="metric"><span>FEASIBLE COMPETITIONS</span><strong>${rows.filter(r=>!r.blocked).length}<span> / ${rows.length}</span></strong><span>Hosting and availability checked</span></div><div class="metric"><span>SUGGESTED SEASON</span><strong>${season.rows.length}<span> / ${season.target} events</span></strong><span>${p.strictRest?'Rest gap required':'Rest gap preferred'}</span></div><div class="metric"><span>KNOWN COST / PERSON</span><strong>${money(season.cost)}</strong><span>${season.unknownCosts?`${season.unknownCosts} trips missing fares; partial total`:'Scenario estimate incl. lodging & fees'}</span></div></div><div class="plan"><h2>A possible route through the season</h2><p class="subtle">${season.shortfall?`${season.shortfall} fewer events than requested under these constraints.`:'Assigned jointly across the circuit, with 6–8 teams per complete field.'}</p><div class="timeline">${season.rows.map(r=>`<div class="stop"><div class="date">${fmt(r.competition.date).toUpperCase()}</div><b>${esc(r.competition.id)}</b><span>${esc(r.competition.city)} · ${r.mode==='drive'?'Drive':'Fly'}</span></div>`).join('')||'<p>No feasible events. Review budget, availability, or strict rest requirements.</p>'}</div><div class="divider" style="border-color:#526e5d"></div><div class="legend" style="color:#d4e2d8;margin-bottom:0">${weeks.map(w=>{const busy=season.rows.find(r=>week(r.competition.date)===w),host=state.competitions.find(c=>c.hosts.includes(selected)&&week(c.date)===w);return `<span>${fmt(new Date((w+5)*86400000).toISOString().slice(0,10))}: <b>${host?'Hosting':busy?esc(busy.competition.id):'Free weekend'}</b></span>`;}).join('')}</div></div><div class="section-head"><div><h2>Competition fit</h2><p class="subtle">Click a competition to inspect the history, edit travel inputs, or search flights.</p></div><span class="tiny">Score out of 100</span></div><div class="table-wrap"><table><thead><tr><th>Competition</th><th>Fit</th><th>History</th><th>Travel</th><th>Trip / person</th><th>Schedule</th></tr></thead><tbody>${sorted.map(r=>`<tr class="${r.blocked?'blocked':chosen.has(r.competition.id)?'picked':''}"><td><button class="row-action" data-detail="${r.competition.id}"><b>${esc(r.competition.id)}</b></button><div class="tiny">${fmt(r.competition.date)} · ${esc(r.competition.city)}</div></td><td>${r.blocked?'—':`<span class="score">${Math.round(r.score)}</span><span class="bar"><i style="width:${r.score}%"></i></span>`}</td><td>${r.history.attended} / ${r.history.opportunities}<div class="tiny">recorded editions</div></td><td>${r.distance===null?'Unknown':`${Math.round(r.distance).toLocaleString()} mi`}<div class="tiny">${r.mode==='drive'?'Drive estimate':'Flight'}${r.mode==='fly'&&r.fare===null?' · fare needed':''}</div></td><td>${money(r.cost)}<div class="tiny">${r.cost!==null?'Estimate':'Add route quote'}</div></td><td>${r.blocked?`<span class="chip block">${esc(r.reasons[0])}</span>`:chosen.has(r.competition.id)?'<span class="chip">Suggested</span>':'Available'}${r.missing.includes('Host not verified')?'<div class="tiny warn-text">Host unverified</div>':''}</td></tr>`).join('')}</tbody></table></div><p class="tiny">Missing prices use a neutral factor (50/100), never a zero-dollar fare. Straight-line distance is shown; driving distance is estimated.</p>`;}
function renderFitMatrix(){const matrix=all();$('#content').innerHTML=`<div class="section-head"><div><h2>The circuit at a glance</h2><p class="subtle">Compare every team. Outlined cells belong to each team’s suggested schedule.</p></div></div><div class="legend"><span><i class="swatch"></i> Higher fit = darker green</span><span>× Hosting / unavailable</span><span>Click a cell for team details</span></div><div class="table-wrap"><table class="heat"><thead><tr><th>Team</th>${state.competitions.map(c=>`<th>${esc(c.id)}<div class="tiny">${fmt(c.date)}</div></th>`).join('')}</tr></thead><tbody>${data.teams.map(t=>`<tr><td>${esc(display(t))}</td>${matrix[t].rows.map(r=>`<td><button aria-label="${esc(t)} at ${esc(r.competition.id)}" data-cell-team="${esc(t)}" data-detail="${r.competition.id}" class="${matrix[t].plan.rows.some(x=>x.competition.id===r.competition.id)?'selected':''}" style="background:${r.blocked?'#f0f0ec':`hsl(90 35% ${97-r.score*.42}%)`}">${r.blocked?'×':Math.round(r.score)}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panel" style="margin-top:20px"><h3>Competition interest</h3><p class="subtle">Jointly allocated lineups. Fields require 6–8 teams; shortages mean the current circuit draft is incomplete.</p><div class="form-grid">${state.competitions.map(c=>{const ts=data.teams.filter(t=>matrix[t].plan.rows.some(r=>r.competition.id===c.id));return `<div class="field"><b>${esc(c.id)} · ${ts.length} teams</b><p class="tiny">${ts.map(esc).join(', ')||'No teams selected'}</p></div>`;}).join('')}</div></div>`;}
function renderInputs(){if(PUBLIC){renderPublicInputs();return;}const p=state.teams[selected],s=state.settings;$('#content').innerHTML=`<div class="section-head"><div><h2>Schedule & planning inputs</h2><p class="subtle">Dates come from the workbook; host schools include your confirmed updates. Travel defaults are editable assumptions.</p></div><button id="reset">Reset scenario</button></div><div class="two-cols"><div class="panel"><h3>${esc(display(selected))}: team constraints</h3><div class="form-grid">${field('Season budget / person ($, 0 = none)','budget',p.budget,{scope:'team'})}${field('Preferred origin airport','airport',p.airport,{type:'text',scope:'team'})}${field('Latitude','lat',p.lat,{min:-90,max:90,step:.00001,scope:'team'})}${field('Longitude','lon',p.lon,{min:-180,max:180,step:.00001,scope:'team'})}</div><p class="tiny">With a budget, trips with unknown costs are excluded until priced. A fare applies only to its saved airport pair and competition date.</p><h3 style="margin-top:20px">Unavailable weekends</h3>${[...new Set(state.competitions.map(c=>c.date))].sort().map(d=>`<label class="check-row"><input data-unavailable="${d}" type="checkbox" ${p.unavailable.includes(d)?'checked':''}>${fmt(d)} · ${state.competitions.filter(c=>c.date===d).map(c=>c.id).join(', ')}</label>`).join('')}${selected==='UVA'?'<p class="subtle"><a href="https://registrar.virginia.edu/calendar/academic/2026-2027" target="_blank" rel="noreferrer">UVA spring recess: March 6–14</a>. GGG overlaps; choose whether that makes your team unavailable.</p>':'<p class="tiny">Academic calendars and team commitments are not yet verified for this team.</p>'}</div><div class="panel"><h3>Shared travel assumptions</h3><div class="form-grid">${field('Drive if distance below (mi)','driveLimit',s.driveLimit)}${field('Road / straight-line factor','roadFactor',s.roadFactor,{min:1,max:3,step:.1})}${field('Driving $ / mile / person','mileCost',s.mileCost,{max:10,step:.01})}${field('Hotel $ / night / person','hotel',s.hotel)}${field('Nights per trip','nights',s.nights,{max:7})}${field('Default event fee / person ($)','fee',s.fee)}${field('Baggage per round trip ($)','bags',s.bags)}${field('Airport transfers / person ($)','transfer',s.transfer)}${field('Recorded seasons to use','lookback',s.lookback,{min:1,max:17})}${field('History half-life (years)','halfLife',s.halfLife,{min:1,max:20})}</div><p class="tiny">Defaults are scenario assumptions, not quotes. Driving assumes shared transport; flight totals include separate baggage and transfer allowances.</p></div></div><h2 style="margin-bottom:15px">2026–2027 competitions</h2><div class="table-wrap"><table><thead><tr><th>Competition</th><th>Date</th><th>Host teams</th><th>Destination airport</th><th>Fee / person</th></tr></thead><tbody>${state.competitions.map(c=>`<tr><td><b>${esc(c.id)}</b><span class="tiny">${esc(c.city)}</span></td><td><input aria-label="${c.id} date" class="cell-input" type="date" data-comp="${c.id}" data-prop="date" value="${c.date}"></td><td><input aria-label="${c.id} hosts" class="cell-input" type="text" data-comp="${c.id}" data-prop="hosts" value="${esc(c.hosts.join(', '))}" placeholder="Unverified" list="teams-list"><div class="tiny">${esc(c.hostSource)}</div></td><td><input aria-label="${c.id} airport" class="cell-input" type="text" maxlength="3" data-comp="${c.id}" data-prop="airport" value="${c.airport}"></td><td><input aria-label="${c.id} fee" class="cell-input" type="number" min="0" data-comp="${c.id}" data-prop="fee" value="${c.fee??s.fee}"></td></tr>`).join('')}</tbody></table></div><datalist id="teams-list">${Object.keys(state.teams).map(t=>`<option value="${esc(t)}">`).join('')}</datalist><p class="tiny">Multiple hosts: enter exact team IDs separated by commas (e.g. BU, Northeastern). Your confirmed hosts are included: BND → Wisconsin; MANIA → Illini; BNB → Northeastern and BU.</p>`;}
function renderDetailBase(){const r=results().rows.find(r=>r.competition.id===detail),c=r.competition,p=state.teams[selected],route=state.routes[`${selected}|${detail}`]||{};$('#content').innerHTML=`<button class="back" id="back">← Back to ${tab==='circuit'?'circuit':tab==='compare'?'comparison':'forecast'}</button><div class="section-head"><div><div class="eyebrow">${esc(display(selected))}</div><h2 style="margin-top:10px">${esc(c.name)}</h2><p>${fmt(c.date)}, 2027 · ${esc(c.city)}</p></div><span class="score">${r.blocked?'Blocked':`${Math.round(r.score)} / 100`}</span></div>${r.blocked?`<div class="panel warn-text">${r.reasons.map(esc).join(' · ')}</div>`:''}<div class="two-cols"><div class="panel"><h3>Why this score?</h3>${Object.entries(r.signals).map(([k,v])=>`<div class="section-head" style="margin:13px 0"><span>${({history:'Attendance history',location:'Distance',flight:'Flight price',cost:'Trip cost',time:'Travel time'})[k]}</span><b>${Math.round(v*100)} / 100</b></div>`).join('')}<p class="tiny">Weighted average before scheduling. Unavailable flight/cost inputs and driving-only flight factors are neutral (50). This is not a probability.</p><div class="divider"></div><h3>Recorded attendance: ${r.history.attended} / ${r.history.opportunities} editions</h3><div class="history-line">${r.history.records.map(x=>`<span class="history-item">${x.season}<br>${x.attended?'Attended':'Not recorded'}</span>`).join('')||'<p class="subtle">No comparable editions in the selected history window.</p>'}</div><p class="tiny">Only seasons where this team has recorded activity and this competition has recorded attendees enter the denominator. Recent seasons matter more.</p></div><div class="panel"><h3>Travel from ${esc(p.city)} to ${esc(c.city)}</h3><p class="subtle">${r.distance===null?'Distance unknown':`${Math.round(r.distance)} straight-line miles`} · ${r.hours===null?'Time unknown':`${r.hours.toFixed(1)} h one-way travel estimate`}</p><label class="field"><span>Travel mode</span><select id="mode"><option value="" ${!route.mode?'selected':''}>Automatic (${r.mode})</option><option value="drive" ${route.mode==='drive'?'selected':''}>Drive</option><option value="fly" ${route.mode==='fly'?'selected':''}>Fly</option></select></label><div class="form-grid">${field('Origin airport','airport',p.airport,{type:'text',scope:'team'})}<label class="field"><span>Destination airport</span><input data-comp="${c.id}" data-prop="airport" value="${c.airport}" maxlength="3"></label></div><button class="primary" id="flight-search" ${provider?'':'disabled'}>Search live Friday–Sunday fare</button><p class="tiny">${provider?'One adult, economy, at most one connection. No booking is made.':'Connect your free account in Flight prices.'}</p>${r.quote?`<p><b>${money(r.fare)} round trip</b></p><p class="tiny">${esc(r.quote.source)} · retrieved ${esc(r.quote.retrievedAt)}${r.quote.expiresAt?` · expires ${esc(r.quote.expiresAt)}`:''}</p>${r.quote.planningSnapshot?`<p class="chip ${Date.parse(r.quote.expiresAt)<=Date.now()?'warn':''}">Saved planning price · fetched ${esc(new Date(r.quote.retrievedAt).toLocaleString())}${Date.parse(r.quote.expiresAt)<=Date.now()?' · older than 6 hours':''}</p>`:''}${r.quote.note?`<p class="tiny">${esc(r.quote.note)}</p>`:''}${r.quote.carriers?`<p class="subtle">Airlines in returned itinerary: ${r.quote.carriers.map(esc).join(', ')}</p>`:''}`:''}<details><summary>Enter a sourced quote or planning estimate</summary><label class="field"><span>Round-trip airfare / person ($)</span><input id="manual-fare" type="number" min="0" value="${r.fare??''}"></label><label class="field"><span>Source URL or assumption description</span><input id="fare-source" placeholder="Expedia quote URL or planning assumption"></label><button id="save-fare">Save route price</button><button id="clear-fare">Clear price</button></details><div class="divider"></div><b>Estimated trip total: ${money(r.cost)} / person</b><p class="tiny">Includes transport, ${state.settings.nights} hotel nights, and competition fee. A single-seat fare does not establish availability for a whole team.</p></div></div><div class="panel"><h3>Schedule considerations</h3><p>${c.hosts.length?`Host team: ${c.hosts.map(esc).join(', ')}. Hosting blocks the whole weekend.`:'Host team unverified. An undiscovered hosting conflict could change this result.'}</p><p>Preferred gap: ${state.settings.spacing/7-1} free weekends. ${p.strictRest?'Required for this team.':'Short gaps reduce the schedule score.'}</p>${selected==='UVA'&&c.date>='2027-03-06'&&c.date<='2027-03-14'?'<p class="warn-text">Overlaps UVA spring recess. Review team availability in Schedule & inputs.</p>':''}<p class="tiny">Workbook source: ${esc(c.source)}. Host source: ${esc(c.hostSource)}.</p></div>`;}
function renderMethod(){$('#content').innerHTML=`<div class="panel method"><h2>How the model works</h2><p>Each team–competition pair gets a transparent 0–100 fit score. A joint circuit allocator proposes schedules with 6–8 teams per competition, subject to hosting, unavailable weekends, no double-booking, optional rest requirements, and an optional per-person budget.</p><ol><li><b>Attendance history.</b> Count actual attendance matrix flags once, excluding nationals. Use the selected recent recorded seasons, with a 3-year default half-life. Restrict comparisons to seasons with observed team activity and a populated competition edition. Two prior-equivalent observations smooth sparse history toward average circuit attendance. “Not recorded” does not mean the team chose not to apply.</li><li><b>Location and travel.</b> State-matched city coordinates come from Open-Meteo / GeoNames. Distance is great-circle mileage; road mileage is a configurable approximation. Preferred airports are editable assumptions. Campus-to-airport time, road traffic, and flight connections need review.</li><li><b>Flight and total cost.</b> Price factors decay as exp(−fare/400) and exp(−trip cost/500); distance uses exp(−miles/700), time uses exp(−hours/8). All scales are model assumptions. Missing quotes get a neutral factor of 0.5. With a budget enabled, unknown-cost trips cannot be scheduled.</li><li><b>Rest weekends.</b> Hosting and competing both count as commitments. Each adjacent pair closer than the preferred gap subtracts penalty × (1 − weeks apart / preferred weeks) from the season score. The strict toggle disallows those short gaps. The allocator prioritizes filling each field to six, places remaining team demand up to eight, then improves fit minus rest penalties. Team targets are upper limits. Incomplete drafts show shortages; the heuristic does not prove infeasibility or global optimality.</li></ol><p>Weights are judgment-based and have not been fitted or calibrated. Scores are relative planning signals, not probabilities. Schedules are allocated jointly with a hard maximum of eight per field. Invitation decisions, applications, acceptance, roster changes, and travel inventory can change actual attendance.</p></div><div class="panel method"><h2>Data connections & coverage</h2><ul><li><b>Schedule:</b> all 17 dates and cities from your 2026–2027 workbook, matched to both screenshots. No claim that these are organizer-confirmed.</li><li><b>Hosts:</b> 14 workbook mappings plus your confirmed hosts: BND → Wisconsin, MANIA → Illini, BNB → Northeastern Nakhraas and BU. Every known host is blocked from all events in its Monday–Sunday week.</li><li><b>Geography:</b> 37 unique city coordinates retrieved from <a href="https://open-meteo.com/en/docs/geocoding-api" target="_blank" rel="noreferrer">Open-Meteo / GeoNames</a>. UW is mapped to Seattle, separate from Wisconsin, supported by <a href="https://s3-us-west-2.amazonaws.com/uw-s3-cdn/wp-content/uploads/sites/12/2021/03/09163145/Minutes-2021-07-BOR.pdf" target="_blank" rel="noreferrer">University of Washington records</a>.</li><li><b>Academic dates:</b> <a href="https://registrar.virginia.edu/calendar/academic/2026-2027" target="_blank" rel="noreferrer">UVA calendar</a> verified: spring recess March 6–14, overlapping GGG. Other teams’ calendars and exams are not verified. Use unavailable-weekend controls as those are confirmed.</li><li><b>Flight prices:</b> ${provider?esc(connectionInfo.provider)+' configured':'no provider connected'}. Open <button class="row-action" data-tab="prices">Flight prices</button> to connect SerpApi’s Free plan (250 searches/month). Keys and prices persist privately in the local backend. Only zero-dollar plans pass the connection check. Background refresh follows your interval and available free quota; older prices remain dated planning estimates.</li><li><b>Historical strength:</b> The selected 2–5 seasons of bid points divided by regular-season appearances, scaled by the 4-point maximum. Competition fields average opponent ratings, excluding the selected team. Schedule averages omit unknown events and show coverage. This retrospective measure is off by default as a ranking weight.</li><li><b>Team colors:</b> reused from the existing bid-points team registry, with <a href="https://www.washington.edu/brand/brand-elements/colors/" target="_blank" rel="noreferrer">UW Seattle purple</a> corrected separately from Wisconsin red. Color accents supplement names; similar university colors are not unique identifiers.</li><li><b>Additional factors:</b> model drive/fly choice, estimated time, baggage, transfers, lodging, fees, budgets, blackouts, and rest preferences. Weather forecasts, school exams, bid status, lodging quotes, and roster availability are not automatically connected. Distant-season weather is not represented as a forecast.</li></ul></div><div class="panel"><h3>Keep your scenario</h3><p class="subtle">Edits stay in this browser. Export a scenario to preserve prices, settings, hosts, and constraints.</p><div class="actions"><button id="download-scenario">Download scenario JSON</button><label class="field" style="margin:0"><span>Restore a scenario</span><input id="import-scenario" type="file" accept=".json"></label></div></div>`;}
const factorNames={history:'Attendance history',location:'Distance',flight:'Flight prices',cost:'Total trip cost',time:'Travel time',strength:'Historical field strength'};
function teamBadge(t){return `<span class="team-badge"><i style="background:${teamColors[t]||'#65766b'}"></i>${esc(display(t))}</span>`;}
function decorateTeams(){
 if(tab==='strength'&&!detail){
  const id=strengthCompetition||state.competitions[0].id;$('#content').insertAdjacentHTML('beforeend',`<section class="panel"><h2>Competition field evidence</h2><label class="field"><span>Competition to inspect</span><select id="strength-competition">${state.competitions.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></section>${strengthEvidence(competitionStrength(data,id,selected,state.settings.strengthLookback),selected)}`);
 }
 if(PUBLIC){document.querySelector('#download-scenario')?.closest('.panel')?.remove();}

 if(!detail&&['team','circuit','compare'].includes(tab)){
  const allocation=circuit();$('#content').insertAdjacentHTML('afterbegin',`<div class="strength-strip capacity-status"><b>${allocation.complete?'All 17 fields have 6–8 teams':'Incomplete circuit draft'}</b><span>${allocation.total} team appearances · maximum 8 per competition</span>${allocation.complete?'':`<details><summary>${allocation.missing} unfilled places — show constraints</summary><p>${allocation.issues.map(esc).join(' ')}</p><p>The search did not find a complete allocation. Review team targets, budgets, availability, and strict rest; a shortage is not proof that no solution exists.</p></details>`}</div>`);
 }

 document.querySelectorAll('[data-cell-team],[data-team-view],[data-remove-compare]').forEach(el=>{const t=el.dataset.cellTeam||el.dataset.teamView||el.dataset.removeCompare;el.style.setProperty('--team-color',teamColors[t]||'#65766b');el.classList.add('team-accent');});
 document.querySelectorAll('.schedule-slot.compete').forEach(el=>{const t=el.querySelector('[data-cell-team]')?.dataset.cellTeam;if(t){el.style.setProperty('--team-color',teamColors[t]||'#65766b');el.classList.add('team-slot');}});
 if(!detail&&tab==='team'){
  const p=results().plan;
  $('#content .plan').insertAdjacentHTML('beforeend',`<details class="plan-math"><summary>Why this combination?</summary><p>${p.rows.map(r=>`${r.competition.id} ${r.score.toFixed(1)}`).join(' + ')||'0'} = ${p.fitTotal.toFixed(1)} total fit points.<br>Subtract ${p.restPenalty.toFixed(1)} points for short rest gaps → <b>${p.value.toFixed(1)} schedule score</b>.</p><p class="tiny">The circuit allocator fills fields to six, then places remaining team demand up to eight, and improves fit and rest through reassignment. Hosting, budget, availability, and strict rest remain hard constraints. This heuristic does not guarantee the global best schedule.</p></details>`);
 }
 if(showStrength&&!detail&&['team','compare','circuit'].includes(tab)){
  if(tab==='team'){
   const p=results().plan,s=scheduleStrength(data,selected,p.rows.map(r=>r.competition.id),null,state.settings.strengthLookback);
   $('#content .metrics').insertAdjacentHTML('afterend',`<div class="strength-strip"><b>Schedule strength: ${strengthNumber(s.score)}</b><span>${s.known}/${s.total} competitions rated from the last ${state.settings.strengthLookback} seasons</span><button class="small" data-tab="strength">Show the evidence</button></div>`);
  }else if(tab==='compare'&&compareMode==='teams'){
   const table=$('#content .comparison-table tbody');if(table)table.insertAdjacentHTML('beforeend',`<tr><th>Historical schedule strength</th>${compareTeams.map(t=>{const s=scheduleStrength(data,t,summary(t).selected,null,state.settings.strengthLookback);return `<td>${strengthNumber(s.score)}<div class="tiny">${s.known}/${s.total} events rated</div></td>`;}).join('')}</tr>`);
  }else if(tab==='circuit'&&circuitView==='calendar'){
   document.querySelectorAll('[data-calendar-comp]').forEach(el=>{const s=competitionStrength(data,el.dataset.calendarComp,null,state.settings.strengthLookback);el.insertAdjacentHTML('beforeend',`<p class="tiny field-strength">Past field strength: <b>${strengthNumber(s.score)}</b> · ${s.editions.length} editions</p>`);});
  }
 }
}
function controls(){const s=state.settings,p=state.teams[selected],total=Object.values(s.weights).reduce((a,b)=>a+b,0);
 $('#controls').innerHTML=`<div class="panel simple-controls"><label class="field" style="margin-top:0"><span>YOUR TEAM</span><select id="team">${data.teams.map(t=>`<option value="${esc(t)}" ${t===selected?'selected':''}>${esc(display(t))}</option>`).join('')}</select></label><p class="subtle">${teamBadge(selected)}<br>${esc(p.city)} · ${esc(p.airport)}</p><div class="compact-fields">${field('Competitions','target',p.target,{max:8,scope:'team'})}<label class="field"><span>Break between events</span><select id="rest">${[0,1,2,3].map(n=>`<option value="${n}" ${s.spacing/7-1===n?'selected':''}>${n===0?'No preference':`${n} free weekend${n>1?'s':''}`}</option>`).join('')}</select></label></div><label class="check-row"><input type="checkbox" id="strict-rest" ${p.strictRest?'checked':''}>Require this break</label><p class="tiny">Hosting also counts as a busy weekend.</p><div class="divider"></div><button class="primary full-width" id="open-whatif">Try what-if models</button><p class="tiny">Preview cheaper travel, stronger fields, recent history, or more recovery.</p><details id="advanced-controls" ${advancedOpen?'open':''}><summary>Adjust model weights & history</summary><label class="field"><span>Attendance history</span><select data-setting="lookback"><option value="2" ${s.lookback===2?'selected':''}>Last 2 seasons</option><option value="5" ${s.lookback===5?'selected':''}>Last 5 recorded seasons</option><option value="17" ${s.lookback===17?'selected':''}>All recorded seasons</option>${![2,5,17].includes(s.lookback)?`<option selected value="${s.lookback}">${s.lookback} seasons</option>`:''}</select></label><div class="weights">${Object.entries(factorNames).map(([k,n])=>`<label><span class="weight-label">${n}<b>${total?Math.round((s.weights[k]||0)/total*100):0}%</b></span><input aria-label="${n} weight" data-weight="${k}" type="range" min="0" max="100" value="${s.weights[k]||0}" style="width:100%"></label>`).join('')}</div><label class="field"><span>Field-strength preference</span><select data-setting="strengthDirection"><option value="1" ${s.strengthDirection===1?'selected':''}>Seek stronger fields</option><option value="0" ${s.strengthDirection===0?'selected':''}>Seek lighter fields</option></select></label><p class="tiny">Strength has no ranking effect at 0% weight.</p>${field('Penalty for short rest','spacingPenalty',s.spacingPenalty,{max:100})}${field('Flight-price multiplier','fareMultiplier',s.fareMultiplier,{min:0,max:5,step:.05})}</details><div class="divider"></div><label class="check-row"><input id="show-strength" type="checkbox" ${showStrength?'checked':''}>Show schedule strength</label><label class="field"><span>Strength history</span><select id="strength-lookback" data-setting="strengthLookback">${[2,3,4,5].map(n=>`<option value="${n}" ${s.strengthLookback===n?'selected':''}>Last ${n} seasons</option>`).join('')}</select></label><button class="small full-width" data-tab="strength">Explore historical strength</button><button class="small full-width" data-tab="prices" style="margin-top:9px">${PUBLIC?'Saved flight prices':provider?'Manage flight connection':'Connect free flight prices'}</button></div>`;
}
function strengthNumber(n){return n===null||n===undefined?'No data':`${n.toFixed(1)} / 100`;}
function renderDetail(){
 renderDetailBase();const r=results().rows.find(r=>r.competition.id===detail),s=state.settings,total=Object.values(s.weights).reduce((a,b)=>a+b,0);
 const explanations={history:`(${r.history.numerator.toFixed(3)} weighted attendances + 2 × ${r.history.prior.toFixed(3)} prior) ÷ (${r.history.denominator.toFixed(3)} opportunities + 2)`,location:r.distance===null?'Missing → neutral':`exp(−${Math.round(r.distance)} miles ÷ ${s.distanceScale})`,flight:r.mode==='drive'?'Driving → neutral':r.modeledFare===null?'Missing fare → neutral':`exp(−${money(r.modeledFare)} ÷ ${money(s.flightScale)})`,cost:r.cost===null?'Unknown total → neutral':`exp(−${money(r.cost)} ÷ ${money(s.costScale)})`,time:r.hours===null?'Missing → neutral':`exp(−${r.hours.toFixed(2)} hours ÷ 8)`,strength:r.strength.score===null?'No historical field → neutral':`${s.strengthDirection===0?'1 − ':''}${r.strength.score.toFixed(2)} ÷ 100`};
 const html=`<section class="panel explanation"><h2>How this score is calculated</h2><p>Every factor is scaled from 0 to 100, then multiplied by its share of the total weight.</p><div class="table-wrap"><table><thead><tr><th>Factor / calculation</th><th>Factor score</th><th>Weight</th><th>Points added</th></tr></thead><tbody>${Object.entries(r.signals).map(([k,v])=>`<tr><td><b>${factorNames[k]}</b><div class="tiny">${esc(explanations[k])}</div></td><td>${(v*100).toFixed(1)}</td><td>${total?((s.weights[k]||0)/total*100).toFixed(1):0}%</td><td><b>+${r.contributions[k].toFixed(2)}</b><span class="contribution-bar" style="width:${Math.max(0,r.contributions[k])*2}px"></span></td></tr>`).join('')}</tbody><tfoot><tr><th>Total before schedule rules</th><td colspan="3"><b>${r.rawScore.toFixed(2)} → ${Math.round(r.rawScore)} displayed</b></td></tr></tfoot></table></div>${r.blocked?`<p class="warn-text">Hard constraint overrides this score: ${r.reasons.map(esc).join('; ')}.</p>`:''}<details><summary>Attendance evidence & recency weights</summary><table><thead><tr><th>Season</th><th>Recorded</th><th>Recency weight</th><th>Source cell</th></tr></thead><tbody>${r.history.records.map(x=>`<tr><td>${x.season}</td><td>${x.attended?'Yes':'No'}</td><td>${x.weight.toFixed(3)}</td><td>${x.source?`${x.season}!${x.source}`:'No attendance flag'}</td></tr>`).join('')}</tbody></table><p class="tiny">Recency weight = 2^(−years before 2025 / ${s.halfLife}). Prior = average field size ÷ distinct active teams in the history window. Source: ${esc(data.source)}.</p></details></section>`;
 $('#content .two-cols').insertAdjacentHTML('beforebegin',html);
 $('#content .two-cols .panel').remove();$('#content .two-cols').style.display='block';
 const transport=r.mode==='drive'?`${r.distance?.toFixed(1)??'?'} straight-line miles × ${s.roadFactor} road factor × 2 directions × $${s.mileCost.toFixed(2)} per mile/person`:`${money(r.fare)} quoted fare × ${s.fareMultiplier} scenario multiplier + ${money(s.bags)} bags + ${money(s.transfer)} transfers`;
 $('#content').insertAdjacentHTML('beforeend',`<div class="panel"><h3>Trip-cost arithmetic</h3><p>${esc(transport)} = <b>${money(r.transport)}</b> transport.</p><p>${money(r.transport)} transport + ${s.nights} nights × ${money(s.hotel)} lodging + ${money(r.competition.fee??s.fee)} event fee = <b>${money(r.cost)} / person</b>.</p><p class="tiny">Missing airfare leaves the total unknown. Driving, lodging, and fee amounts remain scenario estimates. Travel time estimates do not include a verified road route.</p></div><div class="panel"><h3>Historical competition strength</h3><p>Explore opponent ratings and past fields in the separate Historical strength section.</p><button data-strength-comp="${r.competition.id}">View ${r.competition.id} historical strength</button></div>`);
 if(PUBLIC){const travel=$('#content .two-cols');travel.innerHTML=`<div class="panel"><h3>Published travel inputs</h3><p>${esc(state.teams[selected].airport)} → ${esc(r.competition.airport)} · ${r.mode}</p><p>${r.distance===null?'Unknown distance':`${Math.round(r.distance)} straight-line miles`} · ${r.hours?.toFixed(1)??'?'} hours estimated one way</p><p>Airfare: <b>${money(r.fare)}</b> · Trip estimate: <b>${money(r.cost)} / person</b></p>${r.quote?`<p class="tiny">${esc(r.quote.source)} · fetched ${esc(new Date(r.quote.retrievedAt).toLocaleString())}. Saved planning estimate; final booking prices may differ.</p>`:'<p class="tiny">No saved fare for this route yet.</p>'}<p class="tiny">Published prices and competition inputs are read-only.</p></div>`;}
}
function strengthEvidence(strength,t){return `<section class="panel"><h3>Historical field strength: ${strengthNumber(strength.score)}</h3><p class="subtle">Last ${state.settings.strengthLookback} seasons (${strengthSeasons(data,state.settings.strengthLookback).join(", ")}), excluding ${esc(display(t))}. ${strength.knownOpponents} of ${strength.totalOpponents} opponent appearances have ratings. A new competition stays unknown.</p>${strength.editions.map(e=>`<details><summary>${e.season}: ${strengthNumber(e.score)} · ${e.known}/${e.total} rated opponents</summary><table><thead><tr><th>Opponent</th><th>Points / appearances</th><th>Rating</th></tr></thead><tbody>${e.opponents.sort((a,b)=>(b.rating??-1)-(a.rating??-1)).map(o=>`<tr><td>${teamBadge(o.team)}</td><td>${o.rating===null?'No results':`${o.points} ÷ (4 × ${o.appearances}) × 100`}</td><td>${strengthNumber(o.rating)}</td></tr>`).join('')}</tbody></table></details>`).join('')}<p class="tiny">Team rating = 100 × total bid points ÷ (4 × competitions attended) over the selected ${state.settings.strengthLookback} seasons. Each edition averages rated opponents; the event score averages available editions equally. This is retrospective difficulty, not a calibrated win probability.</p></section>`;}
function renderStrength(){
 const ratings=teamRatings(data,state.settings.strengthLookback),p=ratings[selected],current=results(),forecast=scheduleStrength(data,selected,current.plan.rows.map(r=>r.competition.id),null,state.settings.strengthLookback);
 $('#content').innerHTML=`<div class="section-head"><div><h2>Strength of schedule</h2><p class="subtle">Based on ${strengthSeasons(data,state.settings.strengthLookback).join(", ")} results. Separate from attendance fit.</p></div><button id="open-whatif">Try stronger / lighter fields</button></div><div class="metrics"><div class="metric"><span>${esc(display(selected))} · TEAM RATING</span><strong>${p?p.rating.toFixed(1):'—'}</strong><span>${p?`${p.points} bid points across ${p.appearances} appearances`:'No results in the selected window'}</span></div><div class="metric"><span>PROPOSED SCHEDULE STRENGTH</span><strong>${forecast.score===null?'—':forecast.score.toFixed(1)}</strong><span>${forecast.known}/${forecast.total} events have historical fields</span></div><div class="metric"><span>MODEL INFLUENCE</span><strong>${state.settings.weights.strength||0}</strong><span>Relative weight · 0 means display only</span></div></div><div class="panel"><h3>Where the team rating comes from</h3>${p?`<p>${p.points} points ÷ (${p.appearances} appearances × 4 maximum points) × 100 = <b>${p.rating.toFixed(2)}</b></p><table><thead><tr><th>Season</th><th>Bid points</th><th>Appearances</th><th>Workbook source</th></tr></thead><tbody>${p.records.map(r=>`<tr><td>${r.season}</td><td>${r.points}</td><td>${r.appearances}</td><td>${r.source}</td></tr>`).join('')}</tbody></table>`:'<p>Missing recent results are unknown, not zero strength.</p>'}<p class="tiny">Points come from season totals in ${esc(data.source)}; appearances count the regular-season attendance flags. Nationals are excluded. Ratings describe past results, not future roster strength.</p></div><div class="two-cols">${strengthSeasons(data,state.settings.strengthLookback).map(season=>{const history=scheduleStrength(data,selected,[],season,state.settings.strengthLookback);return `<div class="panel"><h3>${season} · historical schedule</h3><p>Opponent strength: <b>${strengthNumber(history.score)}</b></p><table><thead><tr><th>Competition</th><th>Opponent average</th></tr></thead><tbody>${history.events.map(e=>`<tr><td>${esc(e.competition)}</td><td>${strengthNumber(e.score)}</td></tr>`).join('')||'<tr><td colspan="2">No recorded attendance</td></tr>'}</tbody></table></div>`;}).join('')}</div><h3>Upcoming competitions, by historical field strength</h3><div class="table-wrap"><table><thead><tr><th>Competition</th><th>Historical strength</th><th>Rated opponents</th><th>Included editions</th></tr></thead><tbody>${state.competitions.map(c=>({c,strength:competitionStrength(data,c.id,selected,state.settings.strengthLookback)})).sort((a,b)=>(b.strength.score??-1)-(a.strength.score??-1)).map(({c,strength})=>`<tr><td><button class="row-action" data-detail="${c.id}">${esc(c.name)}</button></td><td>${strengthNumber(strength.score)}</td><td>${strength.knownOpponents}/${strength.totalOpponents}</td><td>${strength.editions.map(e=>e.season).join(', ')||'None'}</td></tr>`).join('')}</tbody></table></div><p class="subtle">Schedule strength is the average across rated competitions; unknown events are omitted and coverage is shown. Historical comparisons use pooled opponent ratings from the selected window, so they are retrospective rather than pre-event forecasts. New fields may differ.</p>`;
}
