 $('#content').innerHTML=`<h2>Published competition schedule</h2><p class="subtle">Source dates, hosts, airports, and costs are read-only. Use the sidebar to configure your personal forecast.</p><div class="table-wrap"><table><thead><tr><th>Competition</th><th>Date</th><th>Hosts</th><th>Airport</th><th>Field size</th></tr></thead><tbody>${state.competitions.map(c=>`<tr><td>${esc(c.name)}</td><td>${fmt(c.date)}</td><td>${c.hosts.map(t=>esc(display(t))).join(', ')}</td><td>${esc(c.airport)}</td><td>6–8 teams</td></tr>`).join('')}</tbody></table></div>`;
