function renderPrices(){
 if(PUBLIC){renderPublicPrices();return;}
 const job=connectionInfo.refresh||{},routes=fareRoutes(state,circuit(),fareScope);
 $('#content').innerHTML=`<div class="panel"><div class="eyebrow">BACKEND PRICE CACHE</div><h2 style="margin-top:10px">Connect Google Flights prices</h2><p>Enter your key once. The backend fetches prices, saves them on this computer, and refreshes them on your schedule while the server is running. You can close the browser.</p>${provider?'':`<p><a href="https://serpapi.com/users/sign_up" target="_blank" rel="noreferrer">Get a free SerpApi key</a>, or paste the key you already have below.</p>`}<label class="field"><span>SerpApi private key</span><input id="serp-key" type="password" autocomplete="off" placeholder="Paste key here — not in chat"></label><p class="tiny">The key is saved in a private local backend file, outside browser storage and scenario exports. Disconnect removes that saved key.</p><div class="form-grid"><label class="field"><span>Routes to price</span><select id="fare-scope"><option value="shortlist" ${fareScope==='shortlist'?'selected':''}>Proposed trips + 2 flight alternatives per team</option><option value="all" ${fareScope==='all'?'selected':''}>All eligible flight routes</option></select></label><label class="field"><span>Refresh prices</span><select id="refresh-days">${[[1,'Daily'],[7,'Weekly'],[14,'Every 2 weeks'],[30,'Monthly']].map(([n,label])=>`<option value="${n}" ${refreshDays===n?'selected':''}>${label}</option>`).join('')}</select></label></div><p><b>${routes.length} unique route/date searches</b> in this selection. Proposed trips go first. Shared routes need only one search.</p><div class="actions"><button class="primary" id="connect-serp">Connect & fetch prices</button>${provider?'<button id="start-refresh">Fetch selected routes & enable updates</button><button id="disconnect-serp">Disconnect</button>':''}${job.enabled?'<button id="pause-refresh">Pause updates</button>':''}</div><p class="tiny">Date, airport, or scenario changes do not silently replace the backend queue. Use “Fetch selected routes & enable updates” to apply them. A restart resumes the saved queue.</p></div><div class="panel"><h3>${provider?'Backend connected':'Not connected yet'}</h3><p>${connectionInfo.account?`${connectionInfo.account.remaining} searches remaining of ${connectionInfo.account.limit} on the verified Free plan.`:'No free API key has been verified in this server session yet.'}</p><div class="metrics"><div class="metric"><span>SAVED ROUTES</span><strong>${job.priced||0}<span> / ${job.routes||0}</span></strong></div><div class="metric"><span>DUE FOR LOOKUP</span><strong>${job.due||0}</strong></div><div class="metric"><span>AUTO UPDATE</span><strong style="font-size:20px">${job.enabled?'On':'Off'}</strong><span>Every ${job.intervalDays||refreshDays} days, subject to quota</span></div></div><p role="status" id="refresh-status">${esc(job.message||'Ready to connect.')}${job.busy?' Searching a route…':''}</p>${job.lastUpdated?`<p class="tiny">Latest saved price: ${esc(new Date(job.lastUpdated).toLocaleString())}</p>`:''}${job.nextCheck?`<p class="tiny">Next queue check: ${esc(new Date(job.nextCheck).toLocaleString())}</p>`:''}<p class="subtle">The <a href="https://serpapi.com/pricing" target="_blank" rel="noreferrer">Free plan</a> includes 250 searches/month and 50/hour. This backend uses at most 40 searches/hour and leaves 25 credits for manual lookups. Large selections finish over multiple hours; monthly limits may defer routes until renewal.</p><p class="tiny">Saved prices remain planning estimates after six hours, with their original retrieval dates. Only the outbound itinerary is fetched; return choice, baggage, and team-sized seat availability need checking. Updates require this computer and the local server to stay running; no hosted scheduler is deployed.</p></div>`;
}
async function refreshRequest(body){const response=await fetch('/api/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),result=await response.json();if(!response.ok)throw Error(result.error);connectionInfo=result;provider=result.flights===true;return result;}
async function syncBackend(){let response;try{response=await fetch(PUBLIC?PUBLIC_FEED:'/api/fares');}catch{if(!PUBLIC)throw Error('Backend unavailable');response=await fetch(new URL('fares.json',import.meta.url));}if(!response.ok)return false;const result=await response.json();connectionInfo=result;provider=result.flights===true;const changed=mergeBackendFares(state,result.quotes||[]);if(changed)save();return !!changed;}
function summary(t,matrix=all()){const r=matrix[t];return scheduleSummary(r.rows,r.plan,state.teams[t],state.settings,seasonWeeks(state.competitions));}
function weekDate(w){return new Date((w+5)*86400000).toISOString().slice(0,10);}
function statusLabel(slot){return !slot?'Outside season':slot.kind==='host'?`Hosting ${slot.events.join(' + ')}`:slot.kind==='compete'?slot.events.join(' + '):slot.kind==='unavailable'?'Unavailable':'Free weekend';}
function scheduleCell(t,slot){
 if(!slot)return '<span class="tiny">Outside season</span>';
 if(slot.kind==='compete'||slot.kind==='host')return `<div class="schedule-slot ${slot.kind}">${slot.kind==='host'?'<span class="tiny">HOSTING</span>':''}${slot.events.map(id=>`<button class="row-action" data-cell-team="${esc(t)}" data-detail="${esc(id)}">${esc(id)}</button>`).join(' + ')}</div>`;
 return `<div class="schedule-slot ${slot.kind}">${statusLabel(slot)}</div>`;
}
function circuitSwitcher(){return `<div class="view-switch" role="group" aria-label="Circuit view">${[['calendar','Competition calendar'],['schedules','Team schedules'],['fit','Fit scores']].map(([id,label])=>`<button data-circuit-view="${id}" aria-pressed="${circuitView===id}" class="${circuitView===id?'active':''}">${label}</button>`).join('')}</div>`;}
function renderCircuit(){
 if(circuitView==='fit'){renderFitMatrix();$('#content').insertAdjacentHTML('afterbegin',circuitSwitcher());return;}
 const matrix=all(),weeks=seasonWeeks(state.competitions);
 const intro=`${circuitSwitcher()}<div class="section-head"><div><h2>${circuitView==='calendar'?'The entire competition season':'Every team, every weekend'}</h2><p class="subtle">${state.competitions.length} competitions · ${weeks.length} weekends · ${data.teams.length} teams. Suggested attendance updates with the model.</p></div><button id="export-schedules">Export schedules</button></div>`;
 if(circuitView==='schedules'){
  $('#content').innerHTML=intro+`<div class="legend"><span><i class="swatch"></i>Competing</span><span>Hosting</span><span>Free weekend</span><span>Unavailable</span></div><div class="table-wrap"><table class="schedule-grid"><thead><tr><th>Team</th>${weeks.map(w=>`<th>${fmt(weekDate(w))}<div class="tiny">${state.competitions.filter(c=>week(c.date)===w).map(c=>esc(c.id)).join(' · ')||'No competitions'}</div></th>`).join('')}<th>Events</th><th>Short rest gaps</th></tr></thead><tbody>${data.teams.map(t=>{const s=summary(t,matrix);return `<tr><th><button class="row-action" data-team-view="${esc(t)}">${esc(display(t))}</button></th>${s.timeline.map(slot=>`<td>${scheduleCell(t,slot)}</td>`).join('')}<td>${s.events} / ${s.target}</td><td>${s.shortGaps}</td></tr>`;}).join('')}</tbody></table></div><p class="tiny">Short rest gaps include hosting. Free weekends reflect the current suggested schedule; they are not confirmed time off.</p>`;
  return;
 }
 $('#content').innerHTML=intro+`<p class="subtle">Each card shows the teams whose suggested schedules include that event. Each complete field contains 6–8 teams; these are proposed lineups, not confirmed attendees.</p><div class="calendar-weeks">${weeks.map(w=>`<section class="calendar-week"><div class="week-heading"><h3>Weekend of ${fmt(weekDate(w))}</h3><span class="tiny">${state.competitions.filter(c=>week(c.date)===w).length} competitions</span></div><div class="competition-cards">${state.competitions.filter(c=>week(c.date)===w).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id)).map(c=>{
  const teams=data.teams.filter(t=>matrix[t].plan.rows.some(r=>r.competition.id===c.id)).sort((a,b)=>matrix[b].rows.find(r=>r.competition.id===c.id).score-matrix[a].rows.find(r=>r.competition.id===c.id).score);
  return `<article class="competition-card" data-calendar-comp="${c.id}"><div class="section-head"><h3>${esc(c.name)}</h3><span class="chip ${teams.length<6?'warn':''}">${teams.length} / 6–8 teams${teams.length<6?' · incomplete':''}</span></div><p class="subtle">${esc(c.id)} · ${fmt(c.date)} · ${esc(c.city)}</p><p class="host-line">Hosted by ${c.hosts.map(t=>esc(display(t))).join(' + ')||'Unverified'}</p><div class="team-chips">${teams.map(t=>`<button data-cell-team="${esc(t)}" data-detail="${c.id}">${esc(display(t))}</button>`).join('')||'<span class="tiny">No suggested attendees under current settings.</span>'}</div><details><summary>View other eligible teams</summary><div class="team-chips">${data.teams.filter(t=>!teams.includes(t)&&!matrix[t].rows.find(r=>r.competition.id===c.id).blocked).sort((a,b)=>matrix[b].rows.find(r=>r.competition.id===c.id).score-matrix[a].rows.find(r=>r.competition.id===c.id).score).map(t=>`<button data-cell-team="${esc(t)}" data-detail="${c.id}">${esc(display(t))} · ${Math.round(matrix[t].rows.find(r=>r.competition.id===c.id).score)}</button>`).join('')||'<span class="tiny">No other eligible teams.</span>'}</div></details></article>`;
 }).join('')||'<p class="subtle">No competitions this weekend.</p>'}</div></section>`).join('')}</div>`;
}
function comparePicker(){return `<div class="panel comparison-picker"><div class="team-chips">${compareTeams.map(t=>`<button data-remove-compare="${esc(t)}" aria-label="Remove ${esc(display(t))}" ${compareTeams.length===1?'disabled':''}>${teamBadge(t)} ×</button>`).join('')}</div><label class="field"><span>Add a team to compare (up to 4)</span><select id="compare-add" ${compareTeams.length>=4?'disabled':''}><option value="">Choose a team…</option>${data.teams.filter(t=>!compareTeams.includes(t)).map(t=>`<option value="${esc(t)}">${esc(display(t))}</option>`).join('')}</select></label></div>`;}
function renderCompare(){
 if(compareMode==='whatif'){renderWhatIf();return;}
 const matrix=all(),summaries=Object.fromEntries(compareTeams.map(t=>[t,summary(t,matrix)])),weeks=seasonWeeks(state.competitions),baseline=state.baseline;
 let html=`<div class="section-head"><div><h2>Compare teams & schedules</h2><p class="subtle">Compare up to four teams, or save the current schedules before trying different weights and rest settings.</p></div></div>${comparePicker()}<div class="view-switch" role="group" aria-label="Comparison view"><button data-compare-mode="teams" aria-pressed="${compareMode==='teams'}" class="${compareMode==='teams'?'active':''}">Between teams</button><button data-compare-mode="baseline" aria-pressed="${compareMode==='baseline'}" class="${compareMode==='baseline'?'active':''}">Baseline vs current</button><button data-compare-mode="whatif">What-if models</button></div><div class="actions compare-actions"><button id="capture-baseline">${baseline?'Replace saved baseline':'Save current schedules as baseline'}</button>${baseline?`<span class="subtle">Saved ${esc(new Date(baseline.savedAt).toLocaleString())}</span><button id="clear-baseline" class="small">Clear baseline</button>`:''}</div>`;
 if(compareMode==='baseline'){
  if(!baseline){$('#content').innerHTML=html+'<div class="panel empty"><h3>No baseline saved yet</h3><p>Save the current schedules, then adjust weights, rest gaps, dates, or budgets. This view will show what changed.</p></div>';return;}
  html+=`<p class="subtle">The baseline is a frozen snapshot. Current schedules recalculate with your latest inputs. Costs retain their original assumptions and missing-price labels.</p>`;
  for(const t of compareTeams){
   const before=baseline.teams[t],after=summaries[t];if(!before){html+=`<div class="panel">No baseline for ${esc(display(t))}. Save a new baseline to include this team.</div>`;continue;}
   const added=after.selected.filter(id=>!before.selected.includes(id)),removed=before.selected.filter(id=>!after.selected.includes(id));
   const combined=[...new Set([...before.timeline.map(s=>s.week),...weeks])].sort((a,b)=>a-b);
   html+=`<section class="panel baseline-team"><h3>${esc(display(t))}</h3><div class="baseline-deltas"><span>Events: <b>${before.events} → ${after.events}</b></span><span>Short rest gaps: <b>${before.shortGaps} → ${after.shortGaps}</b></span><span>Known cost: <b>${money(before.cost)} → ${money(after.cost)}</b></span></div><p class="tiny">Unpriced trips: ${before.unknownCosts} baseline / ${after.unknownCosts} current. Cost totals are partial when trips are unpriced.</p><p class="subtle">Added: ${added.map(esc).join(', ')||'None'} · Removed: ${removed.map(esc).join(', ')||'None'}</p><div class="table-wrap"><table class="baseline-table"><thead><tr><th>Weekend</th><th>Saved baseline</th><th>Current schedule</th><th>Change</th></tr></thead><tbody>${combined.map(w=>{const a=before.timeline.find(s=>s.week===w),b=after.timeline.find(s=>s.week===w),changed=statusLabel(a)!==statusLabel(b);return `<tr class="${changed?'changed':''}"><th>${fmt(weekDate(w))}</th><td>${esc(statusLabel(a))}</td><td>${scheduleCell(t,b)}</td><td>${changed?'<span class="chip">Changed</span>':'—'}</td></tr>`;}).join('')}</tbody></table></div></section>`;
  }
 }else{
  const common=state.competitions.filter(c=>compareTeams.length>1&&compareTeams.every(t=>summaries[t].selected.includes(c.id)));
  html+=`<div class="panel"><h3>Shared competitions</h3><p>${common.length?common.map(c=>`${esc(c.name)} (${fmt(c.date)})`).join(' · '):compareTeams.length>1?'No competition is shared by all selected teams in their current schedules.':'Add another team to see shared competitions.'}</p></div><div class="table-wrap"><table class="comparison-table"><thead><tr><th>Season summary</th>${compareTeams.map(t=>`<th>${teamBadge(t)}</th>`).join('')}</tr></thead><tbody>${[
   ['Suggested events',s=>`${s.events} / ${s.target}`],['Free weekends',s=>s.free],['Hosting weekends',s=>s.hosting],['Short rest gaps',s=>s.shortGaps],['Flight trips',s=>s.flights],['Average fit',s=>s.averageFit===null?'—':Math.round(s.averageFit)+' / 100'],['Known cost / person',s=>`${money(s.cost)}${s.unknownCosts?' (partial)':''}`],['Trips missing prices',s=>s.unknownCosts]
  ].map(([label,value])=>`<tr><th>${label}</th>${compareTeams.map(t=>`<td>${value(summaries[t])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h3 style="margin-top:24px">Schedules side by side</h3><div class="table-wrap"><table class="comparison-table"><thead><tr><th>Weekend / competitions</th>${compareTeams.map(t=>`<th>${teamBadge(t)}</th>`).join('')}</tr></thead><tbody>${weeks.map(w=>`<tr><th>${fmt(weekDate(w))}<div class="tiny">${state.competitions.filter(c=>week(c.date)===w).map(c=>esc(c.id)).join(', ')||'No competitions'}</div>${common.some(c=>week(c.date)===w)?'<span class="chip">Shared event</span>':''}</th>${compareTeams.map(t=>`<td>${scheduleCell(t,summaries[t].timeline.find(s=>s.week===w))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h3 style="margin-top:24px">Compare every competition</h3><div class="table-wrap"><table class="comparison-table"><thead><tr><th>Competition</th>${compareTeams.map(t=>`<th>${teamBadge(t)}</th>`).join('')}</tr></thead><tbody>${[...state.competitions].sort((a,b)=>a.date.localeCompare(b.date)).map(c=>`<tr><th>${esc(c.id)}<div class="tiny">${fmt(c.date)}</div></th>${compareTeams.map(t=>{const r=matrix[t].rows.find(r=>r.competition.id===c.id);return `<td><button class="row-action" data-cell-team="${esc(t)}" data-detail="${c.id}">${r.blocked?esc(r.reasons.join('; ')):`${Math.round(r.score)} / 100`}</button>${summaries[t].selected.includes(c.id)?'<div><span class="chip">Suggested</span></div>':''}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;
 }
 $('#content').innerHTML=html;
}
function captureBaseline(){state.baseline={savedAt:new Date().toISOString(),settings:structuredClone(state.settings),teams:Object.fromEntries(data.teams.map(t=>[t,summary(t)]))};save();compareMode='baseline';render();}
function exportSchedules(){const rows=[['Team','Weekend','Status','Competition','Suggested events','Short rest gaps','Known cost USD','Unpriced trips']];for(const t of data.teams){const s=summary(t);for(const slot of s.timeline)rows.push([display(t),weekDate(slot.week),slot.kind,slot.events.join(' + '),s.events,s.shortGaps,s.cost.toFixed(2),s.unknownCosts]);}download('raas-2026-2027-schedules.csv',rows.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv');}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csv(){const lines=[['Team','Competition','Date','Fit score','Blocked reason','Suggested','Recorded attendance','Comparable editions','Distance miles','Mode','Flight USD','Trip estimate USD','Missing inputs']];for(const t of data.teams){const r=all()[t];for(const x of r.rows)lines.push([t,x.competition.id,x.competition.date,x.score===null?'':x.score.toFixed(2),x.reasons.join('; '),r.plan.rows.some(a=>a.competition.id===x.competition.id),x.history.attended,x.history.opportunities,x.distance===null?'':Math.round(x.distance),x.mode,x.fare??'',x.cost??'',x.missing.join('; ')]);}download('raas-2026-2027-rankings.csv',lines.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv');}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.strengthComp){strengthCompetition=b.dataset.strengthComp;tab='strength';detail=null;render();return;}
 if(PUBLIC&&['connect-serp','disconnect-serp','start-refresh','pause-refresh','save-fare','clear-fare','flight-search','import-scenario'].includes(b.id))return;
 if(b.id==='open-whatif'){tab='compare';compareMode='whatif';detail=null;render();}
 if(b.dataset.preset){
  if(!state.baseline)state.baseline={savedAt:new Date().toISOString(),settings:structuredClone(state.settings),teams:Object.fromEntries(data.teams.map(t=>[t,summary(t)]))};
  state=scenarioWithPreset(state,b.dataset.preset);if(['challenge','easier'].includes(b.dataset.preset))showStrength=true;
  save();tab='team';detail=null;message=`Applied ${presets[b.dataset.preset].label}. Compare with the saved baseline to inspect schedule changes.`;render();
 }
 if(b.id==='start-refresh'||b.id==='pause-refresh'){
  b.disabled=true;try{await refreshRequest(b.id==='pause-refresh'?{pause:true}:{routes:fareRoutes(state,circuit(),fareScope),intervalDays:refreshDays,scope:fareScope});message=b.id==='pause-refresh'?'Background updates paused.':'Backend queue saved. Prices will update here as searches finish.';}catch(err){message=err.message;}render();
 }
 if(b.id==='connect-serp'||b.id==='disconnect-serp'){
  const apiKey=$('#serp-key')?.value.trim();if(b.id==='connect-serp'&&!apiKey){message='Enter the key from your free SerpApi account.';render();return;}
  b.disabled=true;const label=b.textContent;b.textContent='Checking account…';if($('#serp-key'))$('#serp-key').value='';
  try{const response=await fetch('/api/connection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b.id==='disconnect-serp'?{disconnect:true}:{apiKey})});const result=await response.json();if(!response.ok)throw Error(result.error);connectionInfo=result;provider=result.flights===true;if(b.id==='disconnect-serp')message='Disconnected. Saved backend key removed; cached prices retained.';else{await refreshRequest({routes:fareRoutes(state,circuit(),fareScope),intervalDays:refreshDays,scope:fareScope});message='Key saved privately. Initial price fetch started; scheduled backend updates are enabled.';}}catch(err){message=err.message;}finally{b.disabled=false;b.textContent=label;render();}
 }
 if(b.dataset.circuitView){circuitView=b.dataset.circuitView;render();}
 if(b.dataset.compareMode){compareMode=b.dataset.compareMode;render();}
 if(b.dataset.removeCompare&&compareTeams.length>1){compareTeams=compareTeams.filter(t=>t!==b.dataset.removeCompare);render();}
 if(b.dataset.teamView){selected=b.dataset.teamView;tab='team';detail=null;render();}
 if(b.id==='capture-baseline'){if(!state.baseline||confirm('Replace the saved baseline with the current schedules?'))captureBaseline();}
 if(b.id==='clear-baseline'){delete state.baseline;save();render();}
 if(b.id==='export-schedules')exportSchedules();
 if(b.dataset.tab){tab=b.dataset.tab;detail=null;message='';render();}
 if(b.dataset.detail){if(b.dataset.cellTeam)selected=b.dataset.cellTeam;detail=b.dataset.detail;render();}
 if(b.id==='back'){detail=null;render();}
 if(b.id==='export')csv();
 if(b.id==='reset'&&confirm('Reset all scenario edits, saved quotes, and constraints to the workbook defaults?')){state=fresh();save();render();}
 if(b.id==='download-scenario')download('raas-scenario.json',JSON.stringify(state,null,2),'application/json');
 if(b.id==='save-fare'){
  const amount=$('#manual-fare').value,source=$('#fare-source').value.trim();if(amount===''||!Number.isFinite(+amount)||+amount<0||!source){message='Enter a nonnegative fare and its source or assumption description.';render();return;}
  const c=state.competitions.find(c=>c.id===detail),key=`${selected}|${detail}`;state.routes[key]??={};state.routes[key].quote={amount:+amount,source,currency:'USD',origin:state.teams[selected].airport,destination:c.airport,competitionDate:c.date,retrievedAt:new Date().toISOString(),expiresAt:new Date(Date.now()+86400000).toISOString()};save();message='Saved route input. Manually entered prices expire after 24 hours.';render();
 }
 if(b.id==='clear-fare'){delete (state.routes[`${selected}|${detail}`]||{}).quote;save();render();}
 if(b.id==='flight-search'){
  b.disabled=true;b.textContent='Searching airlines…';const team=selected,cid=detail,c=state.competitions.find(c=>c.id===cid),origin=state.teams[team].airport;
  try{const response=await fetch('/api/flights',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({origin,destination:c.airport,competitionDate:c.date})});const result=await response.json();if(!response.ok)throw Error(result.error);if(result.account)connectionInfo.account=result.account;if(result.quote){const key=`${team}|${cid}`;state.routes[key]??={};state.routes[key].quote=result.quote;save();message='Live quote saved. Review route details, expiry, and group availability.';}else message=result.message;}catch(err){message=err.message;}render();
 }
});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='strength-competition'){strengthCompetition=el.value;render();return;}
 if(PUBLIC&&(el.dataset.comp||el.id==='mode'||el.id==='import-scenario'||(el.dataset.team&&!['target','budget'].includes(el.dataset.team))))return;
 if(el.id==='fare-scope'){fareScope=el.value;render();return;}
 if(el.id==='refresh-days'){refreshDays=+el.value;return;}
 if(el.id==='show-strength'){showStrength=el.checked;try{localStorage.setItem('raas-show-strength',String(showStrength));}catch{}render();return;}
 if(el.id==='compare-add'){if(el.value&&compareTeams.length<4&&!compareTeams.includes(el.value))compareTeams.push(el.value);render();return;}
 if(el.id==='team'){selected=el.value;detail=null;message='';render();return;}
 if(el.dataset.weight){state.settings.weights[el.dataset.weight]=+el.value;if(Object.values(state.settings.weights).every(v=>v===0))message="All weights are zero. Set at least one positive weight to produce meaningful rankings.";else message="";}
 else if(el.dataset.setting){if(!el.checkValidity())return;state.settings[el.dataset.setting]=+el.value;}
 else if(el.dataset.team){if(!el.checkValidity())return;const key=el.dataset.team;if(key==='airport'&&!/^[A-Za-z]{3}$/.test(el.value)){message='Airport must be a three-letter code.';render();return;}state.teams[selected][key]=key==='airport'?el.value.toUpperCase():+el.value;}
 else if(el.id==='rest')state.settings.spacing=(+el.value+1)*7;
 else if(el.id==='strict-rest')state.teams[selected].strictRest=el.checked;
 else if(el.dataset.unavailable){const p=state.teams[selected];p.unavailable=el.checked?[...new Set([...p.unavailable,el.dataset.unavailable])]:p.unavailable.filter(d=>d!==el.dataset.unavailable);}
 else if(el.dataset.comp){const c=state.competitions.find(c=>c.id===el.dataset.comp),key=el.dataset.prop;if(!el.checkValidity())return;if(key==='hosts'){const hosts=el.value.split(',').map(s=>s.trim()).filter(Boolean);if(hosts.some(h=>!state.teams[h])){message='Use exact team IDs from the roster (e.g. UVA, UConn, Texas, UH).';render();return;}c.hosts=hosts;c.hostSource='Scenario override';}else if(key==='airport'){if(!/^[A-Za-z]{3}$/.test(el.value))throw Error('Airport must be a three-letter code.');c.airport=el.value.toUpperCase();}else c[key]=key==='fee'?+el.value:el.value;}
 else if(el.id==='mode'){const key=`${selected}|${detail}`;state.routes[key]??={};state.routes[key].mode=el.value;}
 else if(el.id==='import-scenario'){const imported=migrateHosts(JSON.parse(await el.files[0].text()),fresh());validateScenario(imported);state=imported;message='Scenario restored.';}
 else return;
 save();render();
 }catch(err){message=err.message;render();}});
document.addEventListener('toggle',e=>{if(e.target.id==='advanced-controls')advancedOpen=e.target.open;},true);
function validateScenario(v){
 if(v?.version!==1||!v.settings||!v.teams||!v.routes||!Array.isArray(v.competitions)||v.competitions.length!==17)throw Error('This is not a supported Raas scenario.');
 for(const [k,value] of Object.entries(defaults)){if(k==='weights')continue;const n=v.settings[k];if(!Number.isFinite(n)||n<0||(value>0&&['halfLife','distanceScale','flightScale','costScale','spacing','roadFactor'].includes(k)&&n===0))throw Error(`Invalid setting: ${k}`);}
 if(![2,3,4,5].includes(v.settings.strengthLookback))throw Error('Strength history must use 2–5 seasons.');
 for(const k of Object.keys(defaults.weights))if(!Number.isFinite(v.settings.weights?.[k])||v.settings.weights[k]<0)throw Error('Invalid weights.');
 for(const t of data.teams){const p=v.teams[t];if(!p||!Number.isInteger(p.target)||p.target<0||p.target>8||!Number.isFinite(p.budget)||p.budget<0||!Number.isFinite(p.lat)||!Number.isFinite(p.lon)||Math.abs(p.lat)>90||Math.abs(p.lon)>180||!Array.isArray(p.unavailable)||p.unavailable.some(d=>!/^\d{4}-\d{2}-\d{2}$/.test(d))||!/^[A-Z]{3}$/.test(p.airport))throw Error(`Invalid team inputs: ${t}`);}
 if(new Set(v.competitions.map(c=>c.id)).size!==17)throw Error('Duplicate competitions.');
 if(v.baseline){
  if(!Number.isFinite(Date.parse(v.baseline.savedAt))||!v.baseline.teams)throw Error('Invalid schedule baseline.');
  for(const s of Object.values(v.baseline.teams)){
   if(!Array.isArray(s.timeline)||!Array.isArray(s.selected)||s.selected.some(x=>typeof x!=='string')||!['events','target','free','hosting','shortGaps','flights','cost','unknownCosts'].every(k=>Number.isFinite(s[k])&&s[k]>=0))throw Error('Invalid schedule baseline summary.');
   if(s.timeline.some(w=>!Number.isFinite(w.week)||!['host','compete','unavailable','free'].includes(w.kind)||!Array.isArray(w.events)||w.events.some(x=>typeof x!=='string')))throw Error('Invalid schedule baseline timeline.');
  }
 }
 for(const c of v.competitions)if(!data.competitions.some(x=>x.id===c.id)||!Array.isArray(c.hosts)||c.hosts.some(t=>!v.teams[t])||!/^\d{4}-\d{2}-\d{2}$/.test(c.date)||!Number.isFinite(day(c.date))||!/^[A-Z]{3}$/.test(c.airport)||!Number.isFinite(c.lat)||!Number.isFinite(c.lon))throw Error('Invalid competition inputs.');
}
try{
 [data,geo]=await Promise.all(['data.json','geography.json'].map(async path=>{const r=await fetch(new URL(path,import.meta.url));if(!r.ok)throw Error(`Could not load ${path}`);return r.json();}));
 state=fresh();try{showStrength=localStorage.getItem('raas-show-strength')==='true';}catch{}try{const saved=localStorage.getItem(KEY);if(saved){const v=migrateHosts(JSON.parse(saved),fresh());validateScenario(v);if(PUBLIC){const base=fresh();v.competitions=base.competitions;v.routes={};for(const t of data.teams)v.teams[t]={...base.teams[t],target:v.teams[t].target,budget:v.teams[t].budget,strictRest:v.teams[t].strictRest,unavailable:v.teams[t].unavailable};}state=v;save();}}catch{message='Saved scenario could not be loaded; workbook defaults are shown.';}
 try{await syncBackend();refreshDays=connectionInfo.refresh?.intervalDays||7;fareScope=connectionInfo.refresh?.scope||(connectionInfo.refresh?.routes===fareRoutes(state,circuit(),'all').length?'all':'shortlist');}catch{}
 render();
 setInterval(async()=>{if(document.hidden||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;try{const changed=await syncBackend();if(changed||(tab==='prices'&&!detail))render();}catch{}},10000);
}catch(err){$('#content').textContent=`Unable to load the planner: ${err.message}. Start the local server using node raas-planner/server.mjs.`;}
